using System.ComponentModel;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

public sealed class WebSearchTool
{
    [Description("Searches the web for information on a given query and returns relevant results.")]
    public static async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        // Simulated web search - in production, integrate with Bing Search API or similar
        await Task.Delay(100); // Simulate network latency

        var results = new List<string>
        {
            $"[Result 1] '{query}' - Overview article from Wikipedia providing foundational context.",
            $"[Result 2] '{query}' - Recent research paper (2026) with latest findings and data.",
            $"[Result 3] '{query}' - Expert blog post discussing practical applications and implications.",
            $"[Result 4] '{query}' - News article from major outlet covering recent developments.",
            $"[Result 5] '{query}' - Technical documentation with detailed specifications.",
        };

        var limitedResults = results.Take(Math.Clamp(maxResults, 1, 10));
        return string.Join(Environment.NewLine, limitedResults);
    }
}

using System.ComponentModel;

namespace ResearchAgent.Tools;

public sealed class NoteTakingTool
{
    private readonly List<string> _notes = [];

    [Description("Saves a research note for later use in the summary. Use this to record key findings.")]
    public string SaveNote(
        [Description("The note content to save")] string content,
        [Description("A short label or category for the note")] string label)
    {
        var entry = $"[{label}] {content}";
        _notes.Add(entry);
        return $"Note saved ({_notes.Count} total): {label}";
    }

    [Description("Retrieves all saved research notes collected so far.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been saved yet.";

        return $"=== Research Notes ({_notes.Count}) ==={Environment.NewLine}" +
               string.Join(Environment.NewLine, _notes.Select((n, i) => $"{i + 1}. {n}"));
    }

    [Description("Clears all saved notes to start fresh.")]
    public string ClearNotes()
    {
        var count = _notes.Count;
        _notes.Clear();
        return $"Cleared {count} notes.";
    }
}

