using Microsoft.Extensions.AI;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Agents.AI.ChatCompletion;
using ResearchAgent.Tools;

// Configuration
var configuration = new ConfigurationBuilder()
    .AddEnvironmentVariables()
    .Build();

var apiKey = configuration["OPENAI_API_KEY"]
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run the research agent.");

var modelId = configuration["OPENAI_MODEL"] ?? "gpt-4o-mini-2024-07-18";

// Set up tools
var noteTaker = new NoteTakingTool();

var tools = new AIFunctionFactory[]
{
}.ToList<object>();

var chatTools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearchTool.SearchWebAsync),
    AIFunctionFactory.Create(noteTaker.SaveNote),
    AIFunctionFactory.Create(noteTaker.GetAllNotes),
    AIFunctionFactory.Create(noteTaker.ClearNotes),
};

// Set up the chat client via MEAI
var services = new ServiceCollection();
services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, apiKey));

var serviceProvider = services.BuildServiceProvider();
var chatClient = serviceProvider.GetRequiredService<IChatClient>();

// Create the agent using Microsoft Agent Framework
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information using the SearchWebAsync tool
        2. Taking notes on key findings using the SaveNote tool
        3. Reviewing your notes using the GetAllNotes tool
        4. Providing a comprehensive summary of your research

        Always search for multiple aspects of the topic, save important findings as notes,
        then compile everything into a clear, well-structured summary.
        """,
};

// Get the research topic
Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");
Console.WriteLine("---");

// Run the agent with tool access
var chatOptions = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
    Tools = chatTools,
};

var agentOptions = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

var messages = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

await foreach (var message in agent.InvokeStreamingAsync(messages, agentOptions, chatOptions))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n--- Research Complete ---");

